// These patterns mirror the server's deterministic, reviewed sentence templates.
// Preserve numeric/date tokens verbatim; never infer or rewrite private/model prose.
export function translatePanelMessage(value: string, locale: "en" | "es"): string {
  if (locale !== "es") return value;
  if (PANEL_COPY[value]) return PANEL_COPY[value];
  const labels: Record<string, string> = { "water access": "acceso al agua", cost: "costo", tools: "herramientas", time: "tiempo", "access to advice": "acceso a orientación", "land-access permission": "permiso de acceso al terreno" };
  const translateSentence = (text: string): string => {
    if (PANEL_COPY[text]) return PANEL_COPY[text];
    let match = /^The seven-day forecast totals (\d+(?:\.\d+)?) mm of precipitation and (\d+(?:\.\d+)?) mm of reference ET0\.$/.exec(text);
    if (match) return `El pronóstico de siete días suma ${match[1]} mm de precipitación y ${match[2]} mm de ET0 de referencia.`;
    match = /^(\d+) days are below the declared one-millimetre daily precipitation threshold; the longest such run inside this forecast is (\d+) days\.$/.exec(text);
    if (match) return `${match[1]} días están bajo el umbral declarado de un milímetro diario de precipitación; la secuencia más larga del pronóstico es de ${match[2]} días.`;
    match = /^(\d+) of seven days are below the declared 1 mm\/day threshold\.$/.exec(text);
    if (match) return `${match[1]} de siete días están bajo el umbral declarado de 1 mm/día.`;
    match = /^The wettest forecast day contains (\d+(?:\.\d+)?)% of the seven-day precipitation total\.$/.exec(text);
    if (match) return `El día con más lluvia prevista reúne el ${match[1]}% de la precipitación total de siete días.`;
    match = /^Your observation on (\d{4}-\d{2}-\d{2}) describes (mostly bare|patchy|well covered) ground cover\.$/.exec(text);
    if (match) return `Tu observación del ${match[1]} describe un suelo ${{ "mostly bare": "mayormente descubierto", patchy: "con cubierta discontinua", "well covered": "bien cubierto" }[match[2]]}.`;
    match = /^You reported (reliable|limited|unreliable) water access; access to water and forecast rainfall are different planning inputs\.$/.exec(text);
    if (match) return `Declaraste un acceso al agua ${{ reliable: "confiable", limited: "limitado", unreliable: "irregular" }[match[1]]}; el acceso al agua y la lluvia prevista son datos de planificación distintos.`;
    match = /^Plan the next conversation around your reported (water access|cost|tools|time|access to advice|land-access permission) constraint and the support available to you\.$/.exec(text);
    if (match) return `Planifica la próxima conversación considerando la dificultad de ${labels[match[1]]} que declaraste y el apoyo disponible.`;
    match = /^Plan around (water access|cost|tools|time|access to advice|land-access permission)$/.exec(text);
    if (match) return `Planificar considerando ${labels[match[1]]}`;
    match = /^Your self-reported field record · (\d{4}-\d{2}-\d{2})$/.exec(text);
    if (match) return `Tu registro de campo declarado · ${match[1]}`;
    return text;
  };
  const parts = value.split(/(?<=\.)\s+(?=[A-Z\d])/);
  const translated = parts.map(translateSentence);
  return translated.every((part, index) => part === parts[index]) ? value : translated.join(" ");
}

export function usePanelCopy() {
  const preferences = useStudioCopy(PANEL_COPY);
  return { ...preferences, t: (value: string) => value.replace(/\S[\s\S]*\S|\S/, text => translatePanelMessage(text, preferences.locale)),
    number: (value: number, digits = 1) => new Intl.NumberFormat(preferences.locale === "es" ? "es-CL" : "en-US", { maximumFractionDigits: digits }).format(value),
    date: (value: string) => new Date(value).toLocaleString(preferences.locale === "es" ? "es-CL" : "en-GB"),
  };
}
